    # ══════════════════════════════════════════════════════════════════════
    {
        "type": "case_study",
        "jurisdiction": "UG",
        "title": "Ugandan Domestic Workers in Saudi Arabia -- Abuse and Death Reports",
        "summary": "Uganda experienced a rapid increase in labour migration to Saudi Arabia from 2016 onward. By 2022, an estimated 50,000+ Ugandan women worked as domestic workers in Saudi Arabia. Reports of abuse mirrored patterns from other East African countries: passport confiscation, 18-hour workdays, physical and sexual violence, denial of food, and wage withholding. The Ugandan embassy in Riyadh reported handling over 100 distress cases monthly. At least 30 Ugandan workers died in Saudi Arabia between 2019 and 2023.",
        "source": "Uganda Ministry of Gender, Labour and Social Development / Daily Monitor / HRW",
    },
    {
        "type": "case_study",
        "jurisdiction": "UG",
        "title": "Ugandan Workers in Oman -- Contract Substitution and Isolation",
        "summary": "Ugandan domestic workers recruited for Oman reported systematic contract substitution upon arrival. Workers promised salaries of USD 300-400/month received USD 150-200. Employers in remote areas kept workers isolated from other Ugandans or embassies. Some workers reported being sold from one employer to another without consent. The Ugandan embassy in Muscat had limited consular capacity to respond. Many workers were unable to communicate distress due to language barriers and confiscated phones.",
        "source": "IOM / Ugandan Ministry of Foreign Affairs / Migrant-Rights.org",
    },
    {
        "type": "case_study",
        "jurisdiction": "UG",
        "title": "Uganda Employment (Recruitment of Ugandan Migrant Workers Abroad) Regulations 2021",
        "summary": "Uganda introduced regulations requiring recruitment agencies to be licensed, pay a UGX 20 million bond, and submit worker contracts for government approval before deployment. Pre-departure orientation became mandatory. Companies were required to facilitate workers' access to Ugandan embassies. However, the External Employment Unit had only 12 staff members to monitor over 200 licensed agencies and an unknown number of unlicensed ones. Irregular recruitment continued largely unchecked, particularly through personal networks.",
        "source": "Uganda Gazette / ILO / Uganda Ministry of Gender, Labour and Social Development",
    },
    {
        "type": "case_study",
        "jurisdiction": "UG",
        "title": "Ugandan Domestic Workers in Kuwait -- Shelter Operations",
        "summary": "The Ugandan embassy in Kuwait operated a small shelter for domestic workers fleeing abusive employers. The shelter housed 15-25 women at any time, with an annual throughput of approximately 200 workers. Women reported severe physical abuse, sexual assault, wage theft, and passport confiscation. Embassy staff helped negotiate settlements with employers and arranged repatriation. Shelter operations were largely funded by IOM and UNHCR. Kuwait authorities provided limited cooperation in prosecuting abusive employers.",
        "source": "Uganda Embassy Kuwait / IOM / Daily Monitor",
    },
    # ══════════════════════════════════════════════════════════════════════
    # 11. UGANDA: TRAFFICKING THROUGH UAE
